import json

TOOLS = {
    'search': {'fn': lambda q: f'results for: {q}', 'schema': {'query': 'str'}},
    'calc': {'fn': lambda expr: str(eval(expr, {'__builtins__': {}})), 'schema': {'expr': 'str'}},
}

def scripted_model(messages):
    n = len([m for m in messages if m['role'] == 'assistant'])
    script = [
        'Thought: I need 14*37. Action: {"tool": "calc", "args": {"expr": "14*37"}}',
        'Thought: I have the answer. Final: 518',
    ]
    return script[min(n, len(script) - 1)]

def run_agent(question, model_fn, max_steps=6):
    messages = [{'role': 'user', 'content': question}]
    trajectory = []
    for _ in range(max_steps):
        turn = model_fn(messages)
        messages.append({'role': 'assistant', 'content': turn})
        trajectory.append(('assistant', turn))
        if 'Final:' in turn:
            return turn.split('Final:', 1)[1].strip(), trajectory
        if 'Action:' in turn:
            action = json.loads(turn.split('Action:', 1)[1].strip())
            name, args = action['tool'], action['args']
            missing = set(TOOLS[name]['schema']) - set(args)
            if missing:
                obs = f'Error: missing args {sorted(missing)}'
            else:
                obs = str(TOOLS[name]['fn'](**args))
            messages.append({'role': 'tool', 'content': obs})
            trajectory.append(('tool', obs))
    return None, trajectory  # step budget exhausted: the off-switch worked

answer, traj = run_agent('What is 14*37?', scripted_model)
print('answer:', answer)
for role, text in traj:
    print(f'[{role}] {text}')

