import json

SCHEMAS = {
    'get_weather': {'location': str, 'units': str},
    'send_email': {'to': str, 'subject': str, 'body': str},
}

def fake_get_weather(location, units='celsius'):
    return f'{location}: 21 {units}'

def fake_send_email(to, subject, body):
    return f'queued email to {to}: {subject}'

DISPATCH = {'get_weather': fake_get_weather, 'send_email': fake_send_email}

def dispatch(raw, budget):
    if budget['remaining'] <= 0:
        return 'Error: tool-call budget exhausted'
    try:
        call = json.loads(raw)
    except json.JSONDecodeError:
        return 'Error: unparseable tool call'
    name, args = call.get('tool'), call.get('args', {})
    if name not in DISPATCH:
        return f'Error: unknown tool {name!r}'
    schema = SCHEMAS[name]
    for k, v in args.items():
        if k not in schema:
            return f'Error: unexpected arg {k!r} for {name}'
        if not isinstance(v, schema[k]):
            return f'Error: arg {k!r} must be {schema[k].__name__}'
    budget['remaining'] -= 1
    try:
        return str(DISPATCH[name](**{k: v for k, v in args.items() if k in schema}))
    except TypeError as e:
        return f'Error: bad arguments for {name}: {e}'

budget = {'remaining': 2}
print(dispatch('{"tool": "get_weather", "args": {"location": "Oslo"}}', budget))
print(dispatch('{"tool": "rm_rf", "args": {}}', budget))
print(dispatch('{"tool": "get_weather", "args": {"location": 5}}', budget))
print('remaining:', budget['remaining'])

class MemoryBuffer:
    def __init__(self, keep_recent=4):
        self.keep_recent = keep_recent
        self.turns = []
        self.summary = ''

    def add(self, role, text):
        self.turns.append((role, text))

    def _compress(self):
        overflow = self.turns[:-self.keep_recent]
        if not overflow:
            return
        bits = '; '.join(f'{r}: {t[:40]}' for r, t in overflow)
        self.summary = (self.summary + ' | ' + bits).strip(' |')
        self.turns = self.turns[-self.keep_recent:]

    def context(self):
        self._compress()
        if self.summary:
            return [('system', 'Summary so far: ' + self.summary)] + self.turns
        return list(self.turns)

    def token_estimate(self):
        return sum(len(t) for _, t in self.context()) // 4

mem = MemoryBuffer(keep_recent=4)
for i in range(7):
    mem.add('user', f'question number {i} about agents and tool use')
    mem.add('assistant', f'answer number {i} with a detailed explanation')
ctx = mem.context()
print('context turns:', len(ctx))
print('summary:', ctx[0][1][:80], '...')
print('token estimate:', mem.token_estimate())
